class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        
        # Check if all indices can be marked at all
        last_occurrence = {}
        for i in range(m):
            last_occurrence[changeIndices[i]] = i + 1
        
        if len(last_occurrence) < n:
            return -1
        
        def can_mark_by_time(t):
            # Try to mark all indices by time t
            # We need to find the last occurrence of each index up to time t
            last_occ = {}
            for i in range(t):
                last_occ[changeIndices[i]] = i
            
            if len(last_occ) < n:
                return False
            
            # Greedy approach: for each index, we mark it at its last occurrence
            # We need to decrement it enough times before marking
            marked = [False] * n
            operations = []  # (time to mark, index, value to decrement)
            
            for idx in range(1, n + 1):
                mark_time = last_occ[idx]
                operations.append((mark_time, idx - 1, nums[idx - 1]))
            
            # Sort by mark time
            operations.sort()
            
            # Simulate the process
            available_time = 0
            op_idx = 0
            
            for sec in range(t):
                if op_idx < len(operations) and operations[op_idx][0] == sec:
                    # This is the time we must mark operations[op_idx][1]
                    needed = operations[op_idx][2]
                    if available_time >= needed:
                        available_time -= needed
                        op_idx += 1
                    else:
                        return False
                else:
                    available_time += 1
            
            return op_idx == len(operations)
        
        # Binary search on the answer
        left, right = 1, m
        result = -1
        
        while left <= right:
            mid = (left + right) // 2
            if can_mark_by_time(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1
        
        return result
